//! Identical-mesh cross-check of the planar `A_z` solver against
//! scikit-fem (the FEM stack used by eMotres/Motor_Ai_Simulation).
//!
//! The fixture is generated by `tools/motor-oracle/az_crosscheck.py`.
//! The affine P1 case assembles the identical discrete system in both
//! codes, so nodal `A_z` must agree to linear-solver tolerance; the
//! nonlinear P1 case shares the same discrete root (Picard there,
//! Newton here); the P2 case compares ordering-invariant scalars.

// Rust guideline compliant 2026-02-21

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde_json::Value;
use sonium_fem::basis::PolynomialDegree;
use sonium_fem::mesh::{ElementType, Mesh, Point};
use sonium_fem::physics::electromagnetics::magnetostatics::BhCurve;
use sonium_fem::physics::electromagnetics::rotating_machine::{
    AzMaterial, AzProblem, AzSolveConfig, MagnetLaw, solve_az,
};

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/motor_oracle/az_crosscheck.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    serde_json::from_str(&text).expect("oracle fixture parses")
}

fn f64s(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("array")
        .iter()
        .map(|entry| entry.as_f64().expect("number"))
        .collect()
}

fn build_mesh(data: &Value) -> Mesh {
    let mut mesh = Mesh::new(2);
    for node in data["nodes"].as_array().expect("nodes") {
        let coords = f64s(node);
        mesh.add_node(Point::new_2d(coords[0], coords[1]));
    }
    let markers = data["markers"].as_array().expect("markers");
    for (element, marker) in data["elements"]
        .as_array()
        .expect("elements")
        .iter()
        .zip(markers)
    {
        let nodes: Vec<usize> = element
            .as_array()
            .expect("element")
            .iter()
            .map(|entry| entry.as_u64().expect("node id") as usize)
            .collect();
        mesh.add_element_with_marker(
            ElementType::Triangle,
            nodes,
            marker.as_i64().expect("marker") as i32,
        );
    }
    mesh.detect_boundaries();
    mesh
}

fn boundary_dofs(mesh: &Mesh, meta: &Value) -> Vec<usize> {
    let domain = f64s(&meta["domain_m"]);
    let [x0, x1, y0, y1] = [domain[0], domain[1], domain[2], domain[3]];
    mesh.nodes
        .iter()
        .enumerate()
        .filter(|(_, node)| {
            (node.x - x0).abs() < 1.0e-12
                || (node.x - x1).abs() < 1.0e-12
                || (node.y - y0).abs() < 1.0e-12
                || (node.y - y1).abs() < 1.0e-12
        })
        .map(|(index, _)| index)
        .collect()
}

fn problem(mesh: Mesh, meta: &Value, nonlinear: bool, degree: PolynomialDegree) -> AzProblem {
    let iron = if nonlinear {
        let points: Vec<(f64, f64)> = meta["bh_points"]
            .as_array()
            .expect("bh points")
            .iter()
            .map(|point| {
                let pair = f64s(point);
                (pair[0], pair[1])
            })
            .collect();
        AzMaterial::nonlinear(BhCurve::new(points).expect("valid B-H curve"))
    } else {
        AzMaterial::linear_mu_r(meta["iron_mu_r"].as_f64().expect("iron mu_r")).unwrap()
    };
    let br = f64s(&meta["magnet_br_t"]);
    let magnet = AzMaterial::magnet(
        MagnetLaw::new(
            meta["magnet_mu_rec"].as_f64().expect("mu_rec"),
            [br[0], br[1]],
        )
        .unwrap(),
    )
    .unwrap();
    AzProblem {
        mesh,
        materials: BTreeMap::from([
            (1, iron),
            (2, magnet),
            (3, AzMaterial::air()),
            (4, AzMaterial::air()),
        ]),
        current_density_a_per_m2: BTreeMap::from([(
            3,
            meta["coil_j_a_per_m2"].as_f64().expect("coil J"),
        )]),
        current_density_fn: None,
        degree,
        quadrature_order: 4,
        stack_length_m: meta["stack_length_m"].as_f64().expect("stack length"),
        conductor_blocks: Vec::new(),
        element_magnet_scale: Vec::new(),
    }
}

/// Identity-gate solve config: this fixture's mesh has no sliver
/// floor, so the Newton can be driven far below the production
/// default (1e-7, the reference's level) and the comparison against
/// scikit-fem stays a same-root identity check.
fn tight_config() -> AzSolveConfig {
    let mut config = AzSolveConfig::default();
    config.newton.relative_tolerance = 1.0e-11;
    config.newton.absolute_tolerance = 1.0e-11;
    config
}

fn relative_l2(actual: &[f64], expected: &[f64]) -> f64 {
    let numerator: f64 = actual
        .iter()
        .zip(expected)
        .map(|(a, e)| (a - e).powi(2))
        .sum::<f64>()
        .sqrt();
    let denominator: f64 = expected.iter().map(|e| e * e).sum::<f64>().sqrt();
    numerator / denominator
}

fn assert_scalar_close(actual: f64, expected: f64, tolerance: f64, label: &str) {
    let scale = expected.abs().max(1.0e-30);
    assert!(
        (actual - expected).abs() / scale < tolerance,
        "{label}: rust {actual} vs oracle {expected}"
    );
}

fn check_case_scalars(
    problem: &AzProblem,
    solution: &sonium_fem::physics::electromagnetics::rotating_machine::AzSolution,
    case: &Value,
    tolerance: f64,
) {
    assert_scalar_close(
        solution.energy.energy_j,
        case["energy_j"].as_f64().expect("energy"),
        tolerance,
        "energy",
    );
    assert_scalar_close(
        solution.energy.coenergy_j,
        case["coenergy_j"].as_f64().expect("coenergy"),
        tolerance,
        "coenergy",
    );
    // Mean A_z over the coil region from the quadrature state, the same
    // quantity the oracle integrates.
    let (mut integral, mut area) = (0.0, 0.0);
    for point in solution
        .quadrature_state
        .iter()
        .filter(|point| point.marker == 3)
    {
        integral += point.vector_potential_wb_per_m * point.integration_weight_m2;
        area += point.integration_weight_m2;
    }
    assert!(area > 0.0, "coil region present");
    assert_scalar_close(
        integral / area,
        case["coil_mean_a_wb_per_m"].as_f64().expect("coil mean A"),
        tolerance,
        "coil mean A",
    );
    // Flux linkage per turn must equal stack_length * coil mean A.
    let linkage = problem
        .coil_flux_linkage_wb_turn(&solution.quadrature_state, 3, 1.0)
        .expect("coil linkage");
    assert_scalar_close(
        linkage,
        case["coil_mean_a_wb_per_m"].as_f64().expect("coil mean A") * problem.stack_length_m,
        tolerance,
        "coil flux linkage",
    );
}

#[test]
fn linear_p1_matches_skfem_on_identical_mesh() {
    let data = fixture();
    let meta = &data["meta"];
    let mesh = build_mesh(&data);
    let dirichlet = boundary_dofs(&mesh, meta);
    let problem = problem(mesh, meta, false, PolynomialDegree::P1);
    let solution =
        solve_az(&problem, &dirichlet, &tight_config(), None, None).expect("linear P1 solve");
    let case = &data["cases"]["linear_p1"];
    let expected = f64s(&case["az"]);
    let error = relative_l2(&solution.vector_potential_wb_per_m, &expected);
    assert!(error < 1.0e-8, "linear P1 nodal A_z rel L2 error {error:e}");
    check_case_scalars(&problem, &solution, case, 1.0e-8);
}

#[test]
fn nonlinear_p1_matches_skfem_picard_root() {
    let data = fixture();
    let meta = &data["meta"];
    let mesh = build_mesh(&data);
    let dirichlet = boundary_dofs(&mesh, meta);
    let problem = problem(mesh, meta, true, PolynomialDegree::P1);
    let solution =
        solve_az(&problem, &dirichlet, &tight_config(), None, None).expect("nonlinear P1 solve");
    let case = &data["cases"]["nonlinear_p1"];
    let expected = f64s(&case["az"]);
    let error = relative_l2(&solution.vector_potential_wb_per_m, &expected);
    assert!(
        error < 1.0e-6,
        "nonlinear P1 nodal A_z rel L2 error {error:e}"
    );
    check_case_scalars(&problem, &solution, case, 1.0e-6);
}

#[test]
fn linear_p2_matches_skfem_scalars_on_identical_mesh() {
    let data = fixture();
    let meta = &data["meta"];
    let mesh = build_mesh(&data).to_p2();
    let dirichlet = boundary_dofs(&mesh, meta);
    let problem = problem(mesh, meta, false, PolynomialDegree::P2);
    let solution =
        solve_az(&problem, &dirichlet, &tight_config(), None, None).expect("linear P2 solve");
    let case = &data["cases"]["linear_p2"];
    check_case_scalars(&problem, &solution, case, 1.0e-7);
    // Vertex values are shared DOFs in both quadratic spaces; their sum
    // and extrema are ordering-invariant. P2 vertices are the original
    // mesh nodes, which precede the promoted edge-midpoint nodes.
    let num_vertices = data["nodes"].as_array().expect("nodes").len();
    let vertices = &solution.vector_potential_wb_per_m[..num_vertices];
    assert_scalar_close(
        vertices.iter().sum(),
        case["vertex_az_sum"].as_f64().expect("vertex sum"),
        1.0e-7,
        "P2 vertex A_z sum",
    );
    assert_scalar_close(
        vertices.iter().copied().fold(f64::INFINITY, f64::min),
        case["vertex_az_min"].as_f64().expect("vertex min"),
        1.0e-7,
        "P2 vertex A_z min",
    );
    assert_scalar_close(
        vertices.iter().copied().fold(f64::NEG_INFINITY, f64::max),
        case["vertex_az_max"].as_f64().expect("vertex max"),
        1.0e-7,
        "P2 vertex A_z max",
    );
}
